// Package procutil holds helpers for cancelling spawned subprocesses.
package procutil

import (
	"os/exec"
	"time"
)

// terminateWaitDelay backstops Wait/Run after ctx-cancel so cancellation is
// bounded even if a descendant keeps an output pipe open.
const terminateWaitDelay = 5 * time.Second

// TerminateOnCancel configures cmd so cancellation cannot leave Wait/Run
// blocked forever on inherited output pipes. Call after building cmd, before
// Start/Run.
//
// On Unix, cmd starts in a new process group and context cancellation SIGKILLs
// the whole group, so agent grandchildren (sandbox helpers, MCP servers, etc.)
// die instead of holding stdout/stderr pipes open. On Windows, process-tree
// killing is not implemented here; only WaitDelay bounds how long Wait/Run can
// remain blocked after cancellation.
func TerminateOnCancel(cmd *exec.Cmd) {
	cmd.WaitDelay = terminateWaitDelay
	killProcessGroupOnCancel(cmd)
}
//go:build unix

package procutil

import (
	"fmt"
	"os/exec"
	"syscall"
)

// killProcessGroupOnCancel SIGKILLs the whole process group on ctx-cancel, so
// grandchildren that inherited the output pipe die too.
func killProcessGroupOnCancel(cmd *exec.Cmd) {
	if cmd.SysProcAttr == nil {
		cmd.SysProcAttr = &syscall.SysProcAttr{}
	}
	cmd.SysProcAttr.Setpgid = true
	cmd.Cancel = func() error {
		if cmd.Process == nil {
			return nil
		}
		// Negative PID = whole group (leader pid == pgid). ESRCH = already exited.
		if err := syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL); err != nil && err != syscall.ESRCH {
			return fmt.Errorf("kill process group: %w", err)
		}
		return nil
	}
}
// Package execx provides explicit helpers for spawning subprocesses with a
// chosen TTY attachment mode, replacing env-var signalling with real OS state.
//
// Use NonInteractive when the subprocess must not prompt (tests, automation,
// hooks that shouldn't block). Use Interactive when the subprocess should
// inherit the parent's controlling TTY (the default for exec.Command).
package execx

import (
	"context"
	"os/exec"
	"time"
)

// NonInteractive returns an *exec.Cmd detached from the parent's controlling
// TTY. In the child, /dev/tty cannot be opened, so
// interactive.CanPromptInteractively() returns false — no env var required.
//
// On Windows the child runs with DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP
// so it has no inherited console.
func NonInteractive(ctx context.Context, name string, args ...string) *exec.Cmd {
	cmd := exec.CommandContext(ctx, name, args...)
	detachFromTTY(cmd)
	return cmd
}

// KillWaitDelay bounds how long Wait blocks after ctx-cancel before exec
// force-closes the subprocess I/O pipes. Without it, a descendant that inherited
// the output pipe (a sandbox or transport helper the direct child spawned) keeps
// the pipe open after the child is killed, so the stdout/stderr copy blocks
// forever and the context deadline is silently defeated.
const KillWaitDelay = 10 * time.Second

// TerminateOnCancel makes cmd and its descendants die when ctx is cancelled.
// exec.Cmd's default Cancel only kills the direct child, leaving a grandchild
// (e.g. a sandbox helper or transport helper) alive and holding the output pipe
// open, which blocks Wait/Run indefinitely past the deadline. A new process
// group lets Cancel SIGKILL the whole tree; WaitDelay is the backstop that
// force-closes the pipes if a descendant escapes the group.
//
// cmd must be created with exec.CommandContext so Cancel runs on ctx-done. Do
// not combine with NonInteractive on the same cmd: NonInteractive sets Setsid,
// which conflicts with the Setpgid this sets.
func TerminateOnCancel(cmd *exec.Cmd) {
	cmd.WaitDelay = KillWaitDelay
	killProcessGroupOnCancel(cmd)
}
	cmd.Stderr = &stderr
	err := cmd.Run()
	// On our timeout the process is killed and Run reports the kill as an
	// *exec.ExitError, which would be indistinguishable from a genuine
	// non-zero exit. Re-wrap with the context error so callers (refLookupAbsent)
	// never mistake a wedged git for a definitive "ref not found".
	if err != nil && ctx.Err() != nil {
		err = fmt.Errorf("git %s timed out after %s: %w", strings.Join(args, " "), reftableGitTimeout, ctx.Err())
	}
	return strings.TrimRight(stdout.String(), "\n"), stderr.Bytes(), err
}

// gitPlumbingEnv builds the environment for a reftable git plumbing command.
// LC_ALL=C / LANG=C force untranslated (English) diagnostics so the stderr
// classification (isRefCASConflict, and RemoveReference's idempotency check)
// stays correct on a localized machine — git's error messages are i18n'd, and
