   190			plumbing.NewHash(initial),
    45			return errors.Join(
    46				fmt.Errorf("ref %s points to %s: %w", refName, target, ErrRefSymbolic),
    47				tx.abort(),
    48			)
    49		}
    50		return tx.commit()
    51	}
    52	
    53	type refCASTransaction struct {
    54		ctx      context.Context
    55		refName  plumbing.ReferenceName
    56		cmd      *exec.Cmd
    57		stdin    io.WriteCloser
    58		stdout   *bufio.Scanner
    59		stderr   bytes.Buffer
    60		done     bool
    61		canceled atomic.Bool
    62	}
    63	
    64	func prepareRefCAS(
    65		ctx context.Context,
    66		repoRoot string,
    67		refName plumbing.ReferenceName,
    68		newHash, expectedHash plumbing.Hash,
    69	) (*refCASTransaction, error) {
    70		if err := refName.Validate(); err != nil {
    71			return nil, fmt.Errorf("validate ref for compare-and-swap: %w", err)
    72		}
    73		oldValue := strings.Repeat("0", newHash.HexSize())
    74		if expectedHash != plumbing.ZeroHash {
    75			oldValue = expectedHash.String()
    76		}
    77	
    78		cmd := exec.CommandContext(ctx, "git", "update-ref", "--stdin")
    79		cmd.Dir = repoRoot
    80		cmd.Env = gitPlumbingEnv()
    81		stdin, err := cmd.StdinPipe()
    82		if err != nil {
    83			return nil, fmt.Errorf("open git update-ref stdin: %w", err)
    84		}
    85		stdout, err := cmd.StdoutPipe()
    86		if err != nil {
    87			_ = stdin.Close()
    88			return nil, fmt.Errorf("open git update-ref stdout: %w", err)
    89		}
    90		tx := &refCASTransaction{
    91			ctx:     ctx,
    92			refName: refName,
    93			cmd:     cmd,
    94			stdin:   stdin,
    95			stdout:  bufio.NewScanner(stdout),
    96		}
    97		cmd.Cancel = func() error {
    98			tx.canceled.Store(true)
    99			_ = stdin.Close()
   100			return nil
   101		}
   102		cmd.Stderr = &tx.stderr
   103		if err := cmd.Start(); err != nil {
   104			_ = stdin.Close()
   105			return nil, fmt.Errorf("start git update-ref transaction for %s: %w", refName, err)
   106		}
   107	
   108		commands := []struct {
   109			request  string
   110			response string
   111		}{
   112			{request: "start", response: "start: ok"},
   113			{request: "option no-deref"},
   114			{request: fmt.Sprintf("update %s %s %s", refName, newHash, oldValue)},
   115			{request: "prepare", response: "prepare: ok"},
   116		}
   117		for _, command := range commands {
   118			if err := tx.exchange(command.request, command.response); err != nil {
   119				return nil, tx.preparationError(err)
   120			}
   121		}
   122		return tx, nil
   123	}
   124	
   125	func (tx *refCASTransaction) exchange(request, response string) error {
   126		if _, err := fmt.Fprintln(tx.stdin, request); err != nil {
   127			return fmt.Errorf("write %q: %w", request, err)
   128		}
   129		if response == "" {
   130			return nil
   131		}
   132		if !tx.stdout.Scan() {
   133			if err := tx.stdout.Err(); err != nil {
   134				return fmt.Errorf("read response to %q: %w", request, err)
   135			}
   136			return fmt.Errorf("read response to %q: %w", request, io.ErrUnexpectedEOF)
   137		}
   138		if got := tx.stdout.Text(); got != response {
   139			return fmt.Errorf("response to %q was %q, want %q", request, got, response)
   140		}
   141		return nil
   142	}
   143	
   144	func (tx *refCASTransaction) preparationError(protocolErr error) error {
   145		waitErr := tx.wait()
   146		if waitErr != nil {
   147			return classifyRefCASError(tx.ctx, tx.refName, tx.stderr.Bytes(), waitErr)
   148		}
   149		return fmt.Errorf("prepare git update-ref transaction for %s: %w", tx.refName, protocolErr)
   150	}
   151	
   152	func (tx *refCASTransaction) commit() error {
   153		return tx.finish("commit", "commit: ok")
   154	}
   155	
   156	func (tx *refCASTransaction) abort() error {
   157		if tx.done {
   158			return nil
   159		}
   160		return tx.finish("abort", "abort: ok")
   161	}
   162	
   163	func (tx *refCASTransaction) finish(request, response string) error {
   164		protocolErr := tx.exchange(request, response)
   165		waitErr := tx.wait()
   166		if waitErr != nil {
   167			return classifyRefCASError(tx.ctx, tx.refName, tx.stderr.Bytes(), waitErr)
   168		}
   169		if protocolErr != nil {
   170			return fmt.Errorf("finish git update-ref transaction for %s: %w", tx.refName, protocolErr)
   171		}
   172		return nil
   173	}
   174	
   175	func (tx *refCASTransaction) wait() error {
   176		if tx.done {
   177			return nil
   178		}
   179		tx.done = true
   180		_ = tx.stdin.Close()

